// ==========================================
// 🛠️ YENİ EKLENEN API: SÜRESİ DOLAN GEÇİCİ KULLANICILARI TEMİZLEME CRON JOB'I
// ==========================================
app.get('/api/cron/temizle-aktiflesmeyenler', async (req, res) => {
    try {
        const besDakikaOnce = new Date(Date.now() - 5 * 60 * 1000).toISOString();

        // active_mi değeri false olan ve son 5 dakikadır onaylanmamış kullanıcıları siler
        const { data, error } = await supabase
            .from('kullanicilar')
            .delete()
            .eq('active_mi', false)
            .lt('created_at', besDakikaOnce);

        if (error) throw error;

        return res.json({ success: true, message: 'Onaylanmamış geçici kullanıcılar başarıyla temizlendi.' });
    } catch (err) {
        console.error("Cron hatası:", err);
        return res.status(500).json({ success: false, error: err.message });
    }
});

// ==========================================
// 🛠️ GÜNCELLENEN API: SAYFALAMA DESTEKLİ MÜŞTERİ LİSTELEME
// ==========================================
app.get('/api/kullanicilar', oturumKontrolu, async (req, res) => {
    try {
        // Query parametrelerinden sayfa ve limit bilgilerini alıyoruz
        const sayfa = parseInt(req.query.sayfa) || 1;
        const limit = parseInt(req.query.limit) || 5; // Varsayılan sınır 5

        const baslangic = (sayfa - 1) * limit;
        const bitis = baslangic + limit - 1;

        // Supabase sorgusuna range ekleyerek sadece istenen adette veriyi getiriyoruz
        const { data, error, count } = await supabase
            .from('kullanicilar')
            .select('*', { count: 'exact' })
            .range(baslangic, bitis);

        if (error) throw error;

        // Hem listeyi hem de toplam kayıt sayısını frontend'e dönüyoruz
        return res.json({ 
            success: true, 
            data: data,
            toplamKayit: count,
            mevcutSayfa: sayfa,
            sayfaBasinaKayit: limit
        });
    } catch (err) {
        return res.status(500).json({ success: false, error: err.message });
    }
});

